// План: .qa/e2e/specs/placement-results.md, группа 1 (тесты 1.1–1.3), кейсы PR-01/02/03/05/07 (.qa/tests/placement-results.md).
// Запасной путь (autotest-writer): адаптивный цикл, window.confirm, два окна, REST. Не прогонять при записи — запуск по /qa-regress.
// Окно ребёнка — asUser('parent'), окно родителя — asUser('parent-3') (refresh-токен одноразовый: одну сессию в двух окнах не использовать).
import { test, expect } from '../../fixtures';
import {
  annotateCleanup,
  createChild,
  levelFromLine,
  levelLines,
  passPlacement,
  qaChildName,
  startPlacementAsChild,
} from './placement.helpers';


// Пропущено 08.11 (решение пользователя): тест создаёт нового ребёнка QA-AUTO и передаёт ему устройство — с #8ca267 режим ребёнка серверный и запирает вход до ввода пароля/PIN.
test.skip(true, 'QA-AUTO + режим ребёнка запирает вход (#8ca267) — пропущено по решению 08.11');

test.describe.configure({ mode: 'serial' });

test.describe('Результаты стартового теста — новый ребёнок (C3 и уровни у родителя)', () => {
  // Общие для 1.1–1.3 данные (serial: при повторе группа идёт заново и создаёт нового ребёнка).
  let childId = '';
  let childName = '';
  let profileReading = 0;
  let profileWriting = 0;

  test('Уверенное прохождение: C3 с подбадриванием без номера уровня, «יאללה, מתחילים!» ведёт к практике @desktop @data #c121d3', async ({ asUser }, testInfo) => {
    test.setTimeout(6 * 60_000); // тест длинный (адаптивное прохождение), это не пауза
    const kid = await asUser('parent');

    childName = qaChildName();
    childId = await createChild(kid, childName);
    annotateCleanup(testInfo, childName, childId);

    await startPlacementAsChild(kid, childId, childName);
    await passPlacement(kid, { reading: 'קל', writing: 'confident' });

    // C3 (AC2; Figma C3 178-2484)
    await expect(kid.getByText(`כל הכבוד, ${childName}!`)).toBeVisible();
    await expect(kid.getByText('סיימנו את המבדק.')).toBeVisible();
    await expect(kid.getByText('איזה יופי, הצלחת! בוא נתחיל לתרגל?')).toBeVisible();
    // Главная и безопасная следующая кнопка (S-07)
    const start = kid.getByRole('button', { name: 'יאללה, מתחילים!' });
    await expect(start).toBeVisible();
    await expect(kid.getByRole('button', { name: 'אחר כך' })).toBeVisible();

    // Ребёнку ни номера уровня, ни балла, ни сравнения (AC2; F-07; D-02). Имя без цифр — значит цифр нет вообще.
    const c3Text = await kid.locator('body').innerText();
    expect(c3Text, 'на C3 нет цифр').not.toMatch(/\d/);
    for (const banned of ['/ 10', '/ 4', 'מתוך', 'רמה', 'ציון', 'נקודות', '%']) {
      expect(c3Text, `на C3 нет «${banned}»`).not.toContain(banned);
    }

    // «יאללה, מתחילים!» → рекомендованная первая практика («תיאור»; AC2 «צעד הבא»)
    await start.click();
    await kid.waitForURL(/\/reading\/[^/]+\/read\?rec=/);
  });

  test('Родитель видит обе раздельные шкалы нового ребёнка @desktop @data #c121d3', async ({ asUser }) => {
    test.skip(!childId, 'нет ребёнка из теста 1.1');
    const parent = await asUser('parent-3');
    await parent.goto(`/children/${childId}`);

    const lines = levelLines(parent);
    await expect(lines.block).toBeVisible(); // AC3; F-07 «נחשפת להורה ולמפעיל בלבד»
    // По одной строке на область
    await expect(lines.reading).toHaveCount(1);
    await expect(lines.writing).toHaveCount(1);
    // Чтение 1–10, письмо 1–4 — шкалы не перепутаны (AC1, AC3; F-07 «הסולמות נפרדים»)
    // Числа на сайте обёрнуты в метки направления U+2066…U+2069 — допускаем их.
    await expect(lines.reading).toHaveText(/קריאה: [\u2066-\u2069]?(10|[1-9]) \/ 10/);
    await expect(lines.reading).not.toContainText('עדיין לא ודאי');
    await expect(lines.writing).toHaveText(/כתיבה: .*[1-4] \/ 4/);
    await expect(lines.writing).not.toContainText('/ 10');

    profileReading = levelFromLine(await lines.reading.innerText(), 10);
    profileWriting = levelFromLine(await lines.writing.innerText(), 4);
  });

  test('Уровни записаны раздельно с источником и причиной (REST skill_levels) @desktop @data #c121d3', async ({ asUser }) => {
    test.skip(!childId || !profileReading, 'нет данных из тестов 1.1–1.2');
    const parent = await asUser('parent-3');

    // Заголовки берём из запроса самого приложения (сессия родителя, без пароля).
    const appRequest = parent.waitForResponse(
      (r) => r.url().includes('/rest/v1/') && !!r.request().headers()['apikey'],
    );
    await parent.goto(`/children/${childId}`);
    const req = (await appRequest).request();
    const all = await req.allHeaders();
    const headers = { apikey: all['apikey'], authorization: all['authorization'] };
    expect(headers.apikey, 'apikey из запроса приложения').toBeTruthy();
    expect(headers.authorization, 'authorization из запроса приложения').toBeTruthy();
    const base = new URL(req.url()).origin;

    const resp = await parent.request.get(`${base}/rest/v1/skill_levels?child_id=eq.${childId}&select=*`, { headers });
    expect(resp.status()).toBe(200);
    const rows: Record<string, unknown>[] = await resp.json();
    // Если записей не 2 или нет source/reason — тест должен упасть (не подгонять ожидание).
    expect(rows, `skill_levels: ${JSON.stringify(rows)}`).toHaveLength(2);

    // TODO verify selector: названия колонок области/шкалы/уровня взяты наугад из вариантов — сверить с реальным ответом.
    const scaleOf = (r: Record<string, unknown>) => Number(r.scale ?? r.scale_size ?? r.max_level);
    const levelOf = (r: Record<string, unknown>) => Number(r.level ?? r.value ?? r.current_level);
    const reading = rows.find((r) => scaleOf(r) === 10);
    const writing = rows.find((r) => scaleOf(r) === 4);
    expect(reading, `запись чтения (шкала 10): ${JSON.stringify(rows)}`).toBeTruthy();
    expect(writing, `запись письма (шкала 4): ${JSON.stringify(rows)}`).toBeTruthy();

    // AC1 / F-07: одно число + размер шкалы
    expect(levelOf(reading!)).toBeGreaterThanOrEqual(1);
    expect(levelOf(reading!)).toBeLessThanOrEqual(10);
    expect(levelOf(writing!)).toBeGreaterThanOrEqual(1);
    expect(levelOf(writing!)).toBeLessThanOrEqual(4);
    // AC5: источник решения и причина
    for (const r of [reading!, writing!]) {
      expect(r.source, `source: ${JSON.stringify(r)}`).toBe('placement');
      expect(r.reason, `reason: ${JSON.stringify(r)}`).toBe('placement_v1');
    }
    // Совпадает с профилем (1.2)
    expect(levelOf(reading!)).toBe(profileReading);
    expect(levelOf(writing!)).toBe(profileWriting);
  });
});
